//! The web bundle: the app built for `wasm32-unknown-unknown`, its JS glue
//! generated by the `wasm-bindgen` CLI (the version `Cargo.lock` pins), and
//! the page that loads it; and what a server needs to hand its files out.

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::{io, run};

pub mod lazy;

/// The Rust target.
pub const TRIPLE: &str = "wasm32-unknown-unknown";

/// How the `wasm-bindgen` CLI is installed, for a message about its absence.
pub const BINDGEN_INSTALL: &str = "cargo install wasm-bindgen-cli";

/// Generates the glue of the module `wasm` into `dir` as `<bin>.js` and
/// `<bin>_bg.wasm`, replacing what was there.
pub fn bindgen(wasm: &Path, dir: &Path, bin: &str) -> Result<(), String> {
    let _ = std::fs::remove_dir_all(dir);
    io(dir, std::fs::create_dir_all(dir))?;
    run(&mut bindgen_command(wasm, dir, bin))
        .map_err(|e| format!("{e} (install the CLI: {BINDGEN_INSTALL})"))
}

/// The `wasm-bindgen` command that generates the glue of `wasm` into `dir`
/// as `<bin>.js` and `<bin>_bg.wasm`, for a caller that adds its own options
/// and runs it; `dir` is to exist.
pub fn bindgen_command(wasm: &Path, dir: &Path, bin: &str) -> Command {
    let mut command = Command::new("wasm-bindgen");
    command
        .args(["--target", "web", "--no-typescript", "--out-name", bin])
        .arg("--out-dir")
        .arg(dir)
        .arg(wasm);
    command
}

/// The service worker's file, beside the page.
pub const WORKER: &str = "sw.js";

/// Writes the page that loads `<bin>.js` as `<dir>/index.html`, with the
/// service worker `worker` beside it when there is one.
pub fn write_index(dir: &Path, bin: &str, worker: Option<&str>) -> Result<PathBuf, String> {
    write_page(dir, bin, &format!("{bin}.js"), None, worker)
}

/// Writes the page titled `title` as `<dir>/index.html`, loading the glue
/// `glue` and, when named, the module `module` beside it rather than the
/// one the glue names; with a service worker, writes it as [`WORKER`]
/// beside the page, which registers it.
pub fn write_page(
    dir: &Path,
    title: &str,
    glue: &str,
    module: Option<&str>,
    worker: Option<&str>,
) -> Result<PathBuf, String> {
    if let Some(worker) = worker {
        let path = dir.join(WORKER);
        io(&path, std::fs::write(&path, worker))?;
    }
    let index = dir.join("index.html");
    io(
        &index,
        std::fs::write(&index, page(title, glue, module, worker.is_some())),
    )?;
    Ok(index)
}

/// The page that loads the app, registering its service worker first when
/// it has one. The canvas fills it edge to edge (the backend keeps content
/// inside the safe area) and nothing scrolls; a dev server adds what runs
/// before the app ahead of its `</head>`.
fn page(title: &str, glue: &str, module: Option<&str>, worker: bool) -> String {
    let init = match module {
        Some(module) => format!(r#"init({{ module_or_path: "./{module}" }})"#),
        None => "init()".to_owned(),
    };
    // Outside a secure context there is no service worker to register.
    let worker = if worker {
        format!(
            "<script>navigator.serviceWorker?.register(\"./{WORKER}\").catch((e) => console.warn(\"the service worker did not register:\", e));</script>\n"
        )
    } else {
        String::new()
    };
    format!(
        r#"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>{title}</title>
<style>html, body {{ height: 100%; margin: 0; overflow: hidden; overscroll-behavior: none; }}</style>
</head>
<body>
{worker}<script type="module">import init from "./{glue}"; {init};</script>
</body>
</html>
"#
    )
}

/// The `Content-Type` of a bundle file (`.wasm` must be `application/wasm`
/// for streaming compilation).
pub fn mime(path: &Path) -> &'static str {
    match path.extension().and_then(|x| x.to_str()) {
        Some("html") => "text/html; charset=utf-8",
        Some("js") => "text/javascript; charset=utf-8",
        Some("wasm") => "application/wasm",
        Some("css") => "text/css; charset=utf-8",
        Some("png" | "apng") => "image/png",
        Some("jpg" | "jpeg") => "image/jpeg",
        Some("gif") => "image/gif",
        Some("webp") => "image/webp",
        Some("avif") => "image/avif",
        Some("bmp") => "image/bmp",
        Some("ico") => "image/x-icon",
        Some("qoi") => "image/qoi",
        Some("svg") => "image/svg+xml",
        Some("json") => "application/json",
        _ => "application/octet-stream",
    }
}

/// The file under `dir` a request target names: `/` is the index; anything
/// that could leave `dir` is refused.
pub fn resolve(dir: &Path, target: &str) -> Option<PathBuf> {
    let path = request_path(target)?;
    let path = if path.is_empty() { "index.html" } else { path };
    let safe = path
        .split('/')
        .all(|part| !part.is_empty() && part != "." && part != ".." && !part.contains('\\'));
    safe.then(|| dir.join(path))
}

/// The path of a request target, without its leading `/`, query or fragment.
pub fn request_path(target: &str) -> Option<&str> {
    Some(target.split(['?', '#']).next()?.trim_start_matches('/'))
}

/// Whether a module of the bundle in `dir` shares its memory (a threaded
/// build), so its page must be isolated across origins.
pub fn shares_memory_in(dir: &Path) -> bool {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return false;
    };
    entries.filter_map(Result::ok).any(|entry| {
        let path = entry.path();
        path.extension().is_some_and(|x| x == "wasm")
            && std::fs::read(&path).is_ok_and(|module| shares_memory(&module))
    })
}

/// Whether the WebAssembly module `wasm` imports or defines a shared
/// memory; `false` for what does not read as a module.
pub fn shares_memory(wasm: &[u8]) -> bool {
    let mut read = WasmReader { bytes: wasm, at: 8 };
    if !wasm.starts_with(b"\0asm") {
        return false;
    }
    while read.at < wasm.len() {
        let (Some(id), Some(size)) = (read.byte(), read.leb()) else {
            return false;
        };
        let Some(end) = read
            .at
            .checked_add(size as usize)
            .filter(|&e| e <= wasm.len())
        else {
            return false;
        };
        let shared = match id {
            2 => read.imports_shared_memory(),
            5 => read.memories_shared(),
            _ => Some(false),
        };
        match shared {
            Some(true) => return true,
            Some(false) => read.at = end,
            None => return false,
        }
    }
    false
}

/// A cursor over a WebAssembly module's bytes.
struct WasmReader<'a> {
    bytes: &'a [u8],
    at: usize,
}

impl WasmReader<'_> {
    fn byte(&mut self) -> Option<u8> {
        let byte = *self.bytes.get(self.at)?;
        self.at += 1;
        Some(byte)
    }

    /// An unsigned LEB128 of at most 64 bits.
    fn leb(&mut self) -> Option<u64> {
        let mut value = 0u64;
        for shift in (0..64).step_by(7) {
            let byte = self.byte()?;
            value |= u64::from(byte & 0x7F) << shift;
            if byte & 0x80 == 0 {
                return Some(value);
            }
        }
        None
    }

    /// The contents of each section of the module `wasm`, by id; `None` for
    /// what does not read as a module.
    fn sections(wasm: &[u8]) -> Option<Vec<(u8, &[u8])>> {
        if !wasm.starts_with(b"\0asm") {
            return None;
        }
        let mut read = WasmReader { bytes: wasm, at: 8 };
        let mut sections = Vec::new();
        while read.at < wasm.len() {
            let id = read.byte()?;
            let size = read.leb()? as usize;
            let end = read.at.checked_add(size).filter(|&e| e <= wasm.len())?;
            sections.push((id, &wasm[read.at..end]));
            read.at = end;
        }
        Some(sections)
    }

    /// The exports of the module `wasm`: each its name, kind and index.
    fn exports(wasm: &[u8]) -> Option<Vec<(String, u8, u32)>> {
        let mut exports = Vec::new();
        for (_, contents) in Self::sections(wasm)?.into_iter().filter(|(id, _)| *id == 7) {
            let mut read = WasmReader {
                bytes: contents,
                at: 0,
            };
            for _ in 0..read.leb()? {
                let name = read.name()?;
                let kind = read.byte()?;
                let index = u32::try_from(read.leb()?).ok()?;
                exports.push((name, kind, index));
            }
        }
        Some(exports)
    }

    /// The modules the module `wasm` imports from, each once, in order.
    fn import_modules(wasm: &[u8]) -> Option<Vec<String>> {
        let mut modules: Vec<String> = Vec::new();
        for (_, contents) in Self::sections(wasm)?.into_iter().filter(|(id, _)| *id == 2) {
            let mut read = WasmReader {
                bytes: contents,
                at: 0,
            };
            for _ in 0..read.leb()? {
                let module = read.name()?;
                read.skip_name()?;
                read.skip_import()?;
                if !modules.contains(&module) {
                    modules.push(module);
                }
            }
        }
        Some(modules)
    }

    /// A name: its length, then its UTF-8.
    fn name(&mut self) -> Option<String> {
        let len = self.leb()? as usize;
        let end = self
            .at
            .checked_add(len)
            .filter(|&e| e <= self.bytes.len())?;
        let name = std::str::from_utf8(&self.bytes[self.at..end])
            .ok()?
            .to_owned();
        self.at = end;
        Some(name)
    }

    /// What an import imports, after its names.
    fn skip_import(&mut self) -> Option<()> {
        match self.byte()? {
            // A function: its type.
            0x00 => drop(self.leb()?),
            // A table: its element type, then its limits.
            0x01 => {
                self.byte()?;
                self.limits_shared()?;
            }
            0x02 => drop(self.limits_shared()?),
            // A global: its value type and mutability.
            0x03 => {
                self.byte()?;
                self.byte()?;
            }
            // A tag: its attribute and type.
            0x04 => {
                self.byte()?;
                self.leb()?;
            }
            _ => return None,
        }
        Some(())
    }

    fn skip_name(&mut self) -> Option<()> {
        let len = self.leb()? as usize;
        self.at = self
            .at
            .checked_add(len)
            .filter(|&e| e <= self.bytes.len())?;
        Some(())
    }

    /// A memory's limits: whether it is shared.
    fn limits_shared(&mut self) -> Option<bool> {
        let flags = self.byte()?;
        self.leb()?;
        if flags & 0x01 != 0 {
            self.leb()?;
        }
        Some(flags & 0x02 != 0)
    }

    /// The import section: whether a memory it imports is shared; `None`
    /// for an import this does not read.
    fn imports_shared_memory(&mut self) -> Option<bool> {
        for _ in 0..self.leb()? {
            self.skip_name()?;
            self.skip_name()?;
            if self.bytes.get(self.at) == Some(&0x02) {
                self.at += 1;
                if self.limits_shared()? {
                    return Some(true);
                }
            } else {
                self.skip_import()?;
            }
        }
        Some(false)
    }

    /// The memory section: whether a memory it defines is shared.
    fn memories_shared(&mut self) -> Option<bool> {
        for _ in 0..self.leb()? {
            if self.limits_shared()? {
                return Some(true);
            }
        }
        Some(false)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_page_loads_the_generated_module() {
        let html = page("demo", "demo.js", None, false);
        assert!(html.contains(r#"import init from "./demo.js"; init();"#));
        assert!(html.contains("viewport-fit=cover"));
        assert!(!html.contains("serviceWorker"));
        let html = page("demo", "demo.0a1b.js", Some("demo_bg.2c3d.wasm"), false);
        assert!(html.contains(
            r#"import init from "./demo.0a1b.js"; init({ module_or_path: "./demo_bg.2c3d.wasm" });"#
        ));
        assert!(html.contains("<title>demo</title>"));
    }

    #[test]
    fn a_worker_is_written_beside_the_page_that_registers_it() {
        let dir = std::env::temp_dir().join(format!("viso-web-worker-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let index = write_index(&dir, "demo", Some("self.x = 1;\n")).unwrap();
        let html = std::fs::read_to_string(&index).unwrap();
        let register = html
            .find("navigator.serviceWorker?.register(\"./sw.js\")")
            .unwrap();
        assert!(register < html.find("import init").unwrap(), "{html}");
        assert_eq!(
            std::fs::read_to_string(dir.join(WORKER)).unwrap(),
            "self.x = 1;\n"
        );
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn served_files_have_their_types_and_stay_in_the_bundle() {
        assert_eq!(mime(Path::new("a/app_bg.wasm")), "application/wasm");
        assert_eq!(mime(Path::new("app.js")), "text/javascript; charset=utf-8");
        assert_eq!(mime(Path::new("index.html")), "text/html; charset=utf-8");
        assert_eq!(mime(Path::new("blob")), "application/octet-stream");
        let dir = Path::new("/b");
        assert_eq!(resolve(dir, "/"), Some(dir.join("index.html")));
        assert_eq!(resolve(dir, "/app.js?v=1"), Some(dir.join("app.js")));
        assert_eq!(resolve(dir, "/../secret"), None);
        assert_eq!(resolve(dir, "/a//b"), None);
        assert_eq!(resolve(dir, "/a\\..\\b"), None);
    }

    /// A module of `sections`, each its id and contents.
    fn module(sections: &[(u8, &[u8])]) -> Vec<u8> {
        let mut wasm = b"\0asm\x01\0\0\0".to_vec();
        for (id, contents) in sections {
            wasm.push(*id);
            wasm.push(contents.len() as u8);
            wasm.extend_from_slice(contents);
        }
        wasm
    }

    #[test]
    fn a_module_shares_its_memory_when_it_imports_or_defines_a_shared_one() {
        // A type section, then one import of a function and one of memory.
        let types: &[u8] = &[1, 0x60, 0, 0];
        let imports = |memory: &[u8]| {
            let mut section = vec![2];
            section.extend_from_slice(b"\x03wbg\x01f\x00\x00");
            section.extend_from_slice(b"\x03wbg\x06memory\x02");
            section.extend_from_slice(memory);
            section
        };
        assert!(shares_memory(&module(&[
            (1, types),
            (2, &imports(&[0x03, 17, 0x80, 0x80, 0x04]))
        ])));
        assert!(!shares_memory(&module(&[
            (1, types),
            (2, &imports(&[0x00, 17]))
        ])));
        // A memory the module defines.
        assert!(shares_memory(&module(&[(5, &[1, 0x03, 1, 2])])));
        assert!(!shares_memory(&module(&[(5, &[1, 0x01, 1, 2])])));
        assert!(!shares_memory(&module(&[(5, &[1, 0x00, 1])])));
        // What does not read as a module.
        assert!(!shares_memory(b"not wasm"));
        assert!(!shares_memory(&module(&[(5, &[9])])));
        assert!(!shares_memory(&[]));
    }
}
